       padding: clamp(1.25rem, 3vw, 2rem);
       border: 1px solid rgba(138, 160, 184, 0.35);
       border-radius: var(--radius);
       background: rgba(255, 255, 255, 0.88);
       box-shadow: var(--shadow);
       backdrop-filter: blur(10px);
     }

     form {
       display: grid;
       gap: 1rem;
     }

     .fields {
       display: grid;
       gap: 1rem;
     }

     .form-field {
       display: grid;
       gap: 0.45rem;
     }

     label {
       font-weight: 600;
     }

     .required {
       color: var(--accent);
       font-weight: 700;
     }

     .helper,
     .error {
       font-size: 0.925rem;
     }

     .helper {
       color: var(--muted);
     }

     .error {
       margin: 0;
       color: var(--error);
     }

     .error[hidden] {
       display: none;
     }

     input {
       width: 100%;
       min-width: 0;
       padding: 0.9rem 1rem;
       border: 1px solid var(--border);
       border-radius: 14px;
       background: var(--surface);
       color: var(--text);
       font: inherit;
       transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
     }

     input::placeholder {
       color: #8b96a8;
     }

     input:hover {
       border-color: var(--border-strong);
     }

     input:focus {
       outline: none;
       border-color: var(--accent);
       box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.16);
     }

     input[aria-invalid="true"] {
       border-color: var(--error);
       box-shadow: 0 0 0 4px rgba(180, 35, 24, 0.12);
     }

     .actions {
       display: flex;
       justify-content: flex-start;
       padding-top: 0.25rem;
     }

     button {
       appearance: none;
       border: 0;
       border-radius: 999px;
       padding: 0.95rem 1.35rem;
       background: linear-gradient(135deg, var(--accent), #4f46e5);
       color: #fff;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       box-shadow: 0 10px 24px rgba(37, 99, 235, 0.26);
       transition: transform 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
     }

     button:hover {
       background: linear-gradient(135deg, var(--accent-hover), #4338ca);
       transform: translateY(-1px);
       box-shadow: 0 14px 30px rgba(37, 99, 235, 0.3);
     }

     button:focus-visible {
       outline: 3px solid #0f172a;
       outline-offset: 3px;
     }

     .status {
       min-height: 1.5rem;
       margin: 0;
       font-size: 0.95rem;
       font-weight: 600;
     }

     .status[data-state="success"] {
       color: #166534;
     }

     @media (min-width: 700px) {
       .fields {
         grid-template-columns: repeat(2, minmax(0, 1fr));
       }

       .field-full {
         grid-column: 1 / -1;
       }
     }

     @media (forced-colors: active) {
       .skip-link,
       .card,
       input,
       button {
         forced-color-adjust: auto;
         background: Canvas;
         color: CanvasText;
         border-color: ButtonBorder;
       }

       .eyebrow,
       .helper,
       .error,
       .status {
         color: CanvasText;
       }

       input:focus,
       button:focus-visible {
         outline-color: Highlight;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>

   <main id="main-content">
     <section class="hero" aria-labelledby="page-title">
       <p class="eyebrow">Support</p>
       <h1 id="page-title">Contact our support team</h1>
       <p class="subtitle">Send a message and we’ll get back to you as soon as possible.</p>
     </section>

     <section class="card" aria-labelledby="form-title">
       <h2 id="form-title">Request help</h2>

       <form id="contact-form" novalidate>
         <div class="fields">
           <div class="form-field field-full">
             <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
             <input id="full-name" name="fullName" type="text" autocomplete="name" required aria-describedby="full-name-error">
             <p class="error" id="full-name-error" hidden>Enter your full name.</p>
           </div>

           <div class="form-field">
             <label for="email">Email address <span class="required" aria-hidden="true">*</span></label>
             <input id="email" name="email" type="email" autocomplete="email" inputmode="email" required aria-describedby="email-error">
             <p class="error" id="email-error" hidden>Enter a valid email address.</p>
           </div>

           <div class="form-field">
             <label for="phone">Phone number</label>
             <input id="phone" name="phone" type="tel" autocomplete="tel" inputmode="tel" aria-describedby="phone-help">
             <p class="helper" id="phone-help">Use a format like +1 555 123 4567 or (555) 123-4567.</p>
           </div>
         </div>

         <div class="actions">
           <button type="submit">Submit request</button>
         </div>

         <p class="status" id="form-status" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('contact-form');
     const status = document.getElementById('form-status');
     const fields = [
       {
         input: document.getElementById('full-name'),
         error: document.getElementById('full-name-error'),
         message: 'Enter your full name.',
         validate: value => value.trim().length > 0
       },
       {
         input: document.getElementById('email'),
         error: document.getElementById('email-error'),
         message: 'Enter a valid email address.',
         validate: value => value.trim().length > 0 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)
       }
     ];

     function setFieldState(field, isValid) {
       field.input.setAttribute('aria-invalid', String(!isValid));
       field.error.hidden = isValid;
       if (!isValid) {
         field.error.textContent = field.message;
       }
     }

     function clearStatus() {
       status.textContent = '';
       status.removeAttribute('data-state');
     }

     form.addEventListener('submit', event => {
       event.preventDefault();
       clearStatus();

       let firstInvalid = null;

       fields.forEach(field => {
         const isValid = field.validate(field.input.value);
         setFieldState(field, isValid);
         if (!isValid && !firstInvalid) {
           firstInvalid = field.input;
         }
       });

       if (firstInvalid) {
         firstInvalid.focus();
         status.textContent = 'Please fix the highlighted fields.';
         return;
       }

       status.textContent = 'Your request is ready to send.';
       status.setAttribute('data-state', 'success');
       form.reset();
       fields.forEach(field => {
         field.input.removeAttribute('aria-invalid');
         field.error.hidden = true;
       });
     });

     fields.forEach(field => {
       field.input.addEventListener('input', () => {
         if (field.input.hasAttribute('aria-invalid')) {
           const isValid = field.validate(field.input.value);
           setFieldState(field, isValid);
         }
       });
     });
   </script>
 </body>
 </html>

